CardSpoke_MODS.register('focus-mode', {
  onLoad: function(ctx) {
    if (document.getElementById('mod-focus-toggle')) return;
    var btn = document.createElement('button');
    btn.id = 'mod-focus-toggle';
    btn.textContent = 'Focus';
    btn.title = 'Toggle Focus Mode';
    btn.setAttribute('aria-label', 'Toggle focus mode');
    btn.addEventListener('click', function() {
      document.body.classList.toggle('mod-focus-active');
      btn.textContent = document.body.classList.contains('mod-focus-active') ? 'Exit Focus' : 'Focus';
    });
    document.body.appendChild(btn);
    ctx.logger.info('Focus Mode ready');
  },
  onDisable: function(ctx) {
    document.body.classList.remove('mod-focus-active');
    var btn = document.getElementById('mod-focus-toggle');
    if (btn) btn.remove();
    ctx.logger.info('Focus Mode disabled');
  },
  onUninstall: function(ctx) {
    document.body.classList.remove('mod-focus-active');
    var btn = document.getElementById('mod-focus-toggle');
    if (btn) btn.remove();
  }
});
